  state.enemies.forEach(function (enemy) { if (enemy.hp <= 0 && (remaining.get(enemy.key) || 0) > 0) { killed++; remaining.set(enemy.key, remaining.get(enemy.key) - 1); } });
  if (!killed) return null;
